#include <iostream>
#include <vector>
#include <sstream>
#include <string>

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<int> R;
    int val;
    while (iss >> val) {
        R.push_back(val);
    }
    int n = R[0];
    int m = R[1];

    if (n == 1) {
        std::cout << 1 << std::endl;
        return 0;
    }

    int a;
    if (n - m > m - 1) {
        a = m + 1;
    } else {
        a = m - 1;
    }

    std::cout << a << std::endl;
    return 0;
}

